(function(){
'use strict';
const repo=window.DaydreamRepository,esc=window.DaydreamDB.escape;
const dlg=document.createElement('dialog');dlg.className='work-dialog export-dialog';document.body.append(dlg);let generation=0,urls=[];
const enc=new TextEncoder();const bytes=s=>enc.encode(s);const join=parts=>{const out=new Uint8Array(parts.reduce((n,p)=>n+p.length,0));let offset=0;for(const p of parts){out.set(p,offset);offset+=p.length;}return out;};
function pdf(pages){const objects=[null],reserve=()=>{objects.push(null);return objects.length-1;},catalog=reserve(),tree=reserve(),destinations=new Map();const ids=pages.map((p,i)=>{for(const id of [p.docId,...(p.docIds||[])])if(id&&!destinations.has(id))destinations.set(id,i);return reserve();});
 function put(id,value){objects[id]=typeof value==='string'?bytes(value):value;}
 function stream(head,payload){return join([bytes(`<< ${head} /Length ${payload.length} >>\nstream\n`),payload,bytes('\nendstream')]);}
 pages.forEach((p,i)=>{const image=reserve(),content=reserve();put(image,stream('/Type /XObject /Subtype /Image /Width 1240 /Height 1754 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode',p.jpeg));put(content,stream('',bytes('q 595 0 0 842 0 0 cm /PageImage Do Q')));const annotations=[];for(const a of p.links){const destination=destinations.get(a.target);if(destination===undefined)continue;const id=reserve();const x=a.x/1240*595,y=842-(a.y+a.h)/1754*842,w=a.w/1240*595,h=a.h/1754*842;put(id,`<< /Type /Annot /Subtype /Link /Rect [${x.toFixed(2)} ${y.toFixed(2)} ${(x+w).toFixed(2)} ${(y+h).toFixed(2)}] /Border [0 0 0] /Dest [${ids[destination]} 0 R /Fit] >>`);annotations.push(`${id} 0 R`);}put(ids[i],`<< /Type /Page /Parent ${tree} 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /PageImage ${image} 0 R >> >> /Contents ${content} 0 R ${annotations.length?`/Annots [${annotations.join(' ')}]`:''} >>`);});
 put(tree,`<< /Type /Pages /Count ${pages.length} /Kids [${ids.map(i=>i+' 0 R').join(' ')}] >>`);put(catalog,`<< /Type /Catalog /Pages ${tree} 0 R >>`);const parts=[bytes('%PDF-1.4\n%Daydream\n')],offsets=[0];let length=parts[0].length;for(let i=1;i<objects.length;i++){offsets.push(length);const object=join([bytes(`${i} 0 obj\n`),objects[i],bytes('\nendobj\n')]);parts.push(object);length+=object.length;}const xref=length;parts.push(bytes(`xref\n0 ${objects.length}\n0000000000 65535 f \n${offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')}trailer\n<< /Size ${objects.length} /Root ${catalog} 0 R >>\nstartxref\n${xref}\n%%EOF`));return join(parts);}
const SCALE=1240/595;
const defaults={family:'"Kulim Park", Arial, sans-serif',size:12,bold:false,italic:false,underline:false,spacing:0};
function inherited(node,state){const out={...state};if(['B','STRONG'].includes(node.tagName))out.bold=true;if(['I','EM'].includes(node.tagName))out.italic=true;if(node.tagName==='U')out.underline=true;const style=window.DaydreamFormat.styles(node);for(const [p,v] of Object.entries(style)){if(p==='font-family')out.family=v;if(p==='font-size'){out.size=parseFloat(v)*(v.endsWith('px')?.75:1);out.explicitSize=true;}if(p==='font-weight')out.bold=v==='bold'||v==='700';if(p==='font-style')out.italic=v==='italic';if(p==='text-decoration')out.underline=v==='underline';if(p==='letter-spacing')out.spacing=parseFloat(v)*.75;if(p==='background-color')out.highlight=v==='transparent'?null:v;}if(node.dataset.document)out.target=node.dataset.document;return out;}
function blocks(html){const host=document.createElement('div');host.innerHTML=window.DaydreamFormat.sanitize(html);const out=[];function runs(node,state){if(node.nodeType===3)return [{text:node.textContent,...state}];if(node.nodeType!==1)return [];if(node.tagName==='BR')return [{text:'\n',...state}];return [...node.childNodes].flatMap(n=>runs(n,inherited(node,state)));}function walk(node,state={...defaults},blockStyle={align:'left',line:1.6,before:0,after:12}){if(node.nodeType===3){if(node.textContent.trim())out.push({...blockStyle,runs:runs(node,state)});return;}if(node.nodeType!==1)return;const tag=node.tagName,next=inherited(node,state),style=window.DaydreamFormat.styles(node),bs={...blockStyle};if(style['text-align'])bs.align=style['text-align'];if(style['line-height'])bs.line=+style['line-height'];if(style['margin-top'])bs.before=parseFloat(style['margin-top']);if(style['margin-bottom'])bs.after=parseFloat(style['margin-bottom']);if(['H2','H3'].includes(tag)){next.bold=true;if(!next.explicitSize)next.size=tag==='H2'?20:16;}if(['UL','OL'].includes(tag)){[...node.children].forEach((li,i)=>out.push({...bs,runs:[{text:tag==='UL'?'• ':`${i+1}. `,...next},...runs(li,inherited(li,next))]}));return;}if(['P','H2','H3','BLOCKQUOTE'].includes(tag)||tag==='DIV'&&!node.querySelector('p,div,h2,h3,ul,ol')){out.push({...bs,runs:runs(node,next)});return;}[...node.childNodes].forEach(n=>walk(n,next,bs));}[...host.childNodes].forEach(n=>walk(n));return out;}
async function renderPages(docs,token,progress,options={}){if(document.fonts){await Promise.all([document.fonts.load('16px "Kulim Park"'),document.fonts.load('16px "Kumbh Sans"')]);await document.fonts.ready;}const pages=[],canvas=document.createElement('canvas');canvas.width=1240;canvas.height=1754;const ctx=canvas.getContext('2d');let y,links=[],docId,title,pageNumber,docIds=[],pendingAnchor=null;
 function font(run){ctx.font=`${run.italic?'italic ':''}${run.bold?'bold ':''}${run.size*SCALE}px ${run.family}`;}
 function width(text,run){font(run);return ctx.measureText(text).width+Math.max(0,Array.from(text).length-1)*run.spacing*SCALE;}
 function begin(){ctx.fillStyle='#fff';ctx.fillRect(0,0,1240,1754);ctx.fillStyle='#666';ctx.font='18px "Kulim Park", Arial, sans-serif';ctx.fillText('DAYDREAM · '+title.slice(0,70),100,65);y=125;links=[];docIds=[];}
 async function finish(){if(token!==generation)throw Error('Export cancelled.');ctx.fillStyle='#555';ctx.font='18px "Kulim Park", Arial, sans-serif';ctx.fillText(String(++pageNumber),1100,1700);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.9));if(!blob)throw Error('This browser could not create a page image.');const jpeg=new Uint8Array(await blob.arrayBuffer());pages.push({jpeg,links:[...links],docId,docIds:[...docIds]});progress(pages.length);await new Promise(resolve=>setTimeout(resolve,0));}
 function draw(text,x,baseline,run,w){const startX=x;font(run);if(run.highlight){ctx.fillStyle=run.highlight;ctx.fillRect(x,baseline-run.size*SCALE,w,run.size*SCALE*1.25);}ctx.fillStyle='#222';if(run.spacing){for(const ch of Array.from(text)){ctx.fillText(ch,x,baseline);x+=ctx.measureText(ch).width+run.spacing*SCALE;}}else ctx.fillText(text,x,baseline);if(run.underline||run.target){ctx.strokeStyle='#444';ctx.lineWidth=1.4;ctx.beginPath();ctx.moveTo(startX,baseline+4);ctx.lineTo(startX+w,baseline+4);ctx.stroke();}}
 async function write(block){const lines=[];let line=[],used=0;const flushLine=()=>{while(line.length&&!line.at(-1).text.trim()){used-=line.pop().w;}lines.push({parts:line,width:used});line=[];used=0;};function add(text,run){const w=width(text,run);if(w>1040){for(const ch of Array.from(text))add(ch,run);return;}if(used+w>1040&&line.length)flushLine();if(!line.length&&!text.trim())return;line.push({text,run,w});used+=w;}
 for(const raw of block.runs){const run={...defaults,...raw};for(const token of run.text.split(/(\s+)/)){if(token.includes('\n')){const pieces=token.split('\n');pieces.forEach((piece,i)=>{if(i)flushLine();if(piece)add(piece,run);});}else if(token)add(token,run);}}if(line.length||!lines.length)flushLine();y+=(block.before||0)*SCALE;
 for(const [i,line] of lines.entries()){const size=Math.max(12,...line.parts.map(p=>p.run.size)),height=size*SCALE*(block.line||1.6);if(y+height>1630){await finish();begin();}if(pendingAnchor){docIds.push(pendingAnchor);pendingAnchor=null;}const baseline=y+size*SCALE;let x=block.align==='right'?1140-line.width:block.align==='center'?100+(1040-line.width)/2:100;const spaces=line.parts.filter(p=>/^\s+$/.test(p.text)).length,extra=block.align==='justify'&&i<lines.length-1&&spaces?(1040-line.width)/spaces:0;for(const part of line.parts){const px=x;draw(part.text,x,baseline,part.run,part.w);if(part.run.target)links.push({target:part.run.target,x:px,y,w:part.w,h:height});x+=part.w+(/^\s+$/.test(part.text)?extra:0);}y+=height;}y+=(block.after??12)*SCALE;}
 if(options.continuous){docId=null;title=options.worldTitle||docs[0].name;pageNumber=0;begin();for(const d of docs){if(d.sectionHeading){if(y+150>1630){await finish();begin();}await write({runs:[{text:d.sectionHeading,...defaults,family:'"Kumbh Sans", Arial, sans-serif',size:22,bold:true}],before:18,after:18});}pendingAnchor=d.id;await write({runs:[{text:d.name,...defaults,family:'"Kumbh Sans", Arial, sans-serif',size:d.id===docs[0].id?26:18,bold:false}],before:12,after:14});for(const block of blocks(d.html))await write(block);}await finish();return pages;}
 if(docs.length>1){docId=null;title='Contents';pageNumber=0;begin();await write({runs:[{text:'Contents',...defaults,size:24,bold:true}]});for(const d of docs)await write({runs:[{text:d.name,...defaults,target:d.id}]});await finish();}
 for(const d of docs){docId=d.id;title=d.name;pageNumber=0;begin();await write({runs:[{text:d.name,...defaults,family:'"Kumbh Sans", Arial, sans-serif',size:24,bold:false}],after:18});for(const block of blocks(d.html))await write(block);await finish();}return pages;}
function release(){urls.forEach(URL.revokeObjectURL);urls=[];}dlg.addEventListener('close',()=>{generation++;release();});
async function open({reality,ids,captureIds,documents,continuous=false}={}){await repo.open();release();const catalog=reality?await repo.all('catalog',reality.id):await repo.all('catalog');const count=documents?documents.length:ids?ids.length:catalog.length;dlg.innerHTML=`<form><div class="dialog-head"><h2>Export your writing</h2><button type="button" data-close aria-label="Close">×</button></div><p>${continuous?'World Manuscript · '+esc(reality?.name||''):captureIds?'Saved Dream Captures':ids?`${count} selected documents`:reality?esc(reality.name):'All saved realities and captures'}</p><label>Format<select name="format"><option value="pdf">PDF</option><option value="jpeg">JPG page images</option></select></label><p class="field-help">Created on your device. Long documents become separate pages. PDF pages preserve their visual appearance; internal links work when their destinations are included.</p><p id="export-progress" role="status" aria-live="polite"></p><div id="export-downloads"></div><div class="dialog-actions"><button type="button" data-close class="secondary-button">Close</button><button class="button" type="submit">Create export</button></div></form>`;dlg.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>dlg.close());dlg.showModal();dlg.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;const token=++generation;const status=dlg.querySelector('#export-progress'),downloads=dlg.querySelector('#export-downloads');try{release();downloads.replaceChildren();status.textContent='Preparing documents…';let docs=documents||[];if(!documents&&!captureIds){for(const m of catalog.filter(d=>!ids||ids.includes(d.id))){const d=await repo.get('documents',m.id);if(d)docs.push(d);}}if(!documents&&(captureIds||!reality&&!ids)){const captures=await repo.all('captures');captures.filter(c=>!captureIds||captureIds.includes(c.id)).forEach(c=>docs.push({id:c.id,name:c.name,html:`<p>${esc(c.text).replace(/\n/g,'<br>')}</p>`}));}if(!docs.length)throw Error('There is no saved writing to export yet.');const pages=await renderPages(docs,token,n=>{status.textContent=`Preparing page ${n}… You can close this dialog to cancel.`;},{continuous,worldTitle:reality?.name});if(token!==generation)return;const format=new FormData(e.target).get('format');function download(blob,name){const url=URL.createObjectURL(blob);urls.push(url);const a=document.createElement('a');a.href=url;a.download=name;a.textContent=`Download ${name}`;a.className='export-download';downloads.append(a);return a;}const name=(continuous?`${reality?.name||'daydream'}-manuscript`:ids?.length===1?docs[0]?.name||'daydream':reality?.name||'daydream').replace(/[^\p{L}\p{N}_-]+/gu,'-').slice(0,80);if(format==='pdf'){const a=download(new Blob([pdf(pages)],{type:'application/pdf'}),`${name}.pdf`);a.click();}else{pages.forEach((p,i)=>download(new Blob([p.jpeg],{type:'image/jpeg'}),`${name}-${String(i+1).padStart(3,'0')}.jpg`));if(pages.length===1)downloads.firstChild.click();}window.dispatchEvent(new CustomEvent('daydream:workspace-action',{detail:{action:'export-ready'}}));status.textContent=`Ready: ${pages.length} ${pages.length===1?'page':'pages'}. ${format==='jpeg'&&pages.length>1?'Download the numbered images below.':''}`;}catch(err){status.textContent=err.message;}finally{button.disabled=false;}};}
window.DaydreamDocumentExport={open,pdf,blocks};
})();
